/** Shapes of viewer/public/data/massing.json.
 *  Generated by src/model/export_massing.py. Keep in step with that script. */

export type Ring = [number, number][];

/** A polygon with an outer shell and any number of holes. The pool deck is
 *  exported as the deck with the pool cut out, so holes are not optional. */
export interface Poly {
  shell: Ring;
  holes: Ring[];
}

export interface OptionMetrics {
  groundM2: number;
  firstM2: number;
  openGroundM2: number;
  poolDeckM2: number;
  coolingPmShade: number;
  coolingPmShadeMin: number;
  winterMiddaySun: number;
  byHour: Record<string, number>;
  poolNearestSide: number;
  poolFaces: string;
}

export interface WallToBoundary {
  side: number;
  adjacency: string;
  distanceM: number;
  isMainAccess: boolean;
  meetsSetback: boolean;
  from: [number, number];
  to: [number, number];
}

export interface MassingOption {
  key: string;
  name: string;
  summary: string;
  ground: Poly[];
  first: Poly[];
  garage: Poly[];
  pool: Poly[];
  deck: Poly[];
  driveway: Poly[];
  wallToBoundary: WallToBoundary[];
  metrics: OptionMetrics;
}

export interface Facade {
  side: number;
  compass: string;
  azimuth: number;
  adjacency: string;
  annual: number;
  summerAm: number;
  summerPm: number;
}

export interface SideInfo {
  id: number;
  adjacency: string;
  start: [number, number];
  end: [number, number];
  isMainAccess: boolean;
}

export interface WallSpec {
  solid: number;
  screenTo: number;
  treatment: string;
}

export interface MassingData {
  meta: {
    stamp: string;
    plot: string;
    community: string;
    phase: number;
    note: string;
  };
  site: {
    latitude: number;
    longitude: number;
    timezone: string;
    trueNorthVerified: boolean;
    plotAreaM2: number;
    maxGfaM2: number;
    setbackM: number;
    gridBearingDeg: number;
  };
  plot: Ring;
  envelope: Ring;
  sides: SideInfo[];
  heights: { ground: number; first: number; parapet: number; overall: number };
  boundaryWall: { heightM: number; bySide: Record<string, WallSpec> };
  facades: Facade[];
  options: MassingOption[];
  recommended: string;
  sun: {
    hours: number[];
    months: number[];
    table: { month: number; altitude: number[]; azimuth: number[] }[];
  };
}
